mapper.select:
select dish.id,dish.name, category_id, price, image, description, dish.status, dish.update_time, category.name as categoryName
from dish left join category on dish.category_id = category.id


        and dish.name like concat('%',${name},'%')


        and category_id = #{categoryId}


        and dish.status = #{status}


order by update_time desc
